(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-942":{scenario:{company:"Công ty TNHH Linh kiện Điện tử Hòa An",supervisor:{name:"Đinh Thị Ngọc Lan",role:{vi:"Trưởng phòng An toàn - Môi trường",en:"Environment, Health & Safety Manager"}},ref_code:"WST-Q3-25",title:{vi:"Phân loại đúng chất thải. Tính đúng tỷ lệ tái chế. Chuyển giao hợp pháp.",en:"Right waste class. Right recycling rate. Lawful handover."},brief:{vi:"Bạn lập báo cáo chất thải quý III WST-Q3-25 của nhà máy. Giẻ lau, găng tay dính dầu khoáng và dung môi từ xưởng bảo trì đang được ghi là chất thải công nghiệp thông thường. Tổng chất thải rắn phát sinh 486 tấn: tái chế 213.6 tấn, ủ phân hữu cơ 48 tấn, đốt thu hồi năng lượng 72.9 tấn, chôn lấp 151.5 tấn. Đối chiếu bản nháp với hồ sơ đã duyệt, sửa nhóm phân loại và tỷ lệ tái chế (%, 1 chữ số thập phân), rồi lập báo cáo có căn cứ.",en:"You are preparing the plant's Q3 waste report WST-Q3-25. Rags and gloves contaminated with mineral oil and solvents from the maintenance shop are recorded as ordinary industrial waste. Total solid waste was 486 t: recycled 213.6 t, composted 48 t, incinerated with energy recovery 72.9 t, landfilled 151.5 t. Compare the draft with the approved file, correct the waste class and the recycling rate (%, 1 decimal), then write an evidence-based report."},reference_title:{vi:"Sổ phân định & bảng cân đối chất thải đã duyệt · WST-Q3-25",en:"Approved waste classification & balance file · WST-Q3-25"},fields:[{id:"WASTE_CLASS",label:{vi:"Nhóm phân loại giẻ lau, găng tay dính dầu",en:"Class of oily rags and gloves"},initial:"NON-HAZ-IND",expected:"HAZARDOUS",choices:["HAZARDOUS","NON-HAZ-IND","DOMESTIC"],reference:"Sổ phân định chất thải",hint:{vi:"Giẻ lau, vật liệu thấm hút nhiễm dầu và dung môi mang thành phần nguy hại nên phải quản lý như chất thải nguy hại.",en:"Rags and absorbents contaminated with oil and solvents carry hazardous components and must be managed as hazardous waste."}},{id:"RECYCLE_PCT",label:{vi:"Tỷ lệ tái chế quý III (%)",en:"Q3 recycling rate (%)"},initial:"68.8",expected:"53.8",reference:"Bảng cân đối chất thải quý III",ref_value:{vi:"Tổng 486 t; tái chế 213.6 t; ủ phân 48 t; đốt thu hồi năng lượng 72.9 t; chôn lấp 151.5 t",en:"Total 486 t; recycled 213.6 t; composted 48 t; energy recovery 72.9 t; landfill 151.5 t"},hint:{vi:"Theo thứ bậc quản lý chất thải, thu hồi năng lượng đứng sau tái chế và không được tính là tái chế.",en:"In the waste hierarchy energy recovery ranks below recycling and does not count as recycling."}}],sop32:{vi:"Tỷ lệ tái chế = (khối lượng tái chế + ủ phân hữu cơ) / tổng chất thải phát sinh x 100; đốt thu hồi năng lượng và chôn lấp không được tính; làm tròn 1 chữ số thập phân.",en:"Recycling rate = (recycled + composted) / total waste generated x 100; energy recovery and landfill are excluded; round to 1 decimal place."},context:{label:"BÁO CÁO CHẤT THẢI / WST-Q3-25",metrics:[{label:{vi:"Tổng chất thải rắn",en:"Total solid waste"},value:"486 t"},{label:{vi:"Đốt thu hồi năng lượng",en:"Energy recovery"},value:"72.9 t"},{label:{vi:"Chôn lấp",en:"Landfill"},value:"151.5 t"}]},crisis:{vi:"Trưởng phòng Mua hàng nhắn: “Có đơn vị thu gom rẻ hơn 40%, không có giấy phép xử lý chất thải nguy hại nhưng nhận cả giẻ dầu. Cứ trộn chung vào chất thải thường giao cho họ, khỏi làm chứng từ.”",en:"The Purchasing Manager texts: “A collector is 40% cheaper. They have no hazardous waste permit but will take the oily rags. Mix them into general waste for them and skip the manifest.”"},options:{safe:{vi:"Từ chối trộn và chuyển giao trái phép; lưu giữ riêng chất thải nguy hại, chỉ giao cho đơn vị có giấy phép kèm chứng từ chất thải nguy hại; báo Trưởng phòng An toàn - Môi trường.",en:"Refuse mixing and unlawful handover; store hazardous waste separately, hand it only to a permitted operator with a manifest, and inform the EHS Manager."},shortcut:{vi:"Trộn giẻ dầu vào chất thải thường và giao cho đơn vị giá rẻ để tiết kiệm chi phí.",en:"Mix the oily rags into general waste and give them to the cheap collector."},wait:{vi:"Để giẻ dầu tồn đọng trong kho, không trả lời và chờ hợp đồng mới.",en:"Leave the oily rags piling up in storage, ignore the message and wait for a new contract."}},questions:{vi:["Vì sao giẻ lau, găng tay dính dầu phải xếp HAZARDOUS? Căn cứ phân định nào trong hồ sơ chứng minh?","Trình bày cách tính tỷ lệ tái chế và trách nhiệm của chủ nguồn thải khi giao chất thải nguy hại cho đơn vị không có giấy phép."],en:["Why must the oily rags and gloves be classed HAZARDOUS? Which classification evidence supports it?","Explain how you calculated the recycling rate and the generator's liability when handing hazardous waste to an unpermitted operator."]},hints:{vi:["Đối chiếu thành phần và nguồn phát sinh của giẻ lau với tiêu chí phân định chất thải nguy hại trong sổ phân định.","Chỉ cộng tái chế và ủ phân ở tử số theo SOP mục 3.2; mẫu số là tổng chất thải phát sinh.","Đọc lại SOP mục 4.2: chất thải nguy hại chỉ được chuyển giao cho đơn vị có giấy phép, kèm chứng từ."],en:["Check the rags' composition and source against the hazardous waste criteria in the classification register.","Only recycling and composting go in the numerator in SOP 3.2; the denominator is total waste generated.","Re-read SOP 4.2: hazardous waste goes only to permitted operators, always with a manifest."]}},learning:{summary:{vi:"Chuyên viên quản lý chất thải và kinh tế tuần hoàn phân định, thu gom, lưu giữ, chuyển giao chất thải đúng quy định; thiết kế chương trình giảm thiểu, tái sử dụng, tái chế và thu hồi vật liệu; theo dõi số liệu, báo cáo và thực hiện trách nhiệm mở rộng của nhà sản xuất (EPR). Nghề đòi hỏi am hiểu pháp luật môi trường, quy trình sản xuất, chuỗi cung ứng tái chế và tư duy thiết kế vòng đời sản phẩm.",en:"A waste management and circular economy specialist classifies, collects, stores and hands over waste lawfully; designs reduction, reuse, recycling and material recovery programs; tracks data, reports and delivers extended producer responsibility (EPR). The role needs knowledge of environmental law, production processes, recycling supply chains and life-cycle thinking."},responsibilities:{vi:["Phân định, phân loại chất thải tại nguồn và quản lý khu lưu giữ chất thải nguy hại.","Lựa chọn, giám sát đơn vị thu gom, xử lý có giấy phép và quản lý chứng từ chất thải nguy hại.","Theo dõi cân đối khối lượng chất thải, tỷ lệ tái chế và lập báo cáo định kỳ.","Thiết kế chương trình giảm thiểu, tái sử dụng bao bì, cộng sinh công nghiệp và thu hồi vật liệu.","Thực hiện nghĩa vụ trách nhiệm mở rộng của nhà sản xuất (EPR) và đào tạo người lao động."],en:["Classify and segregate waste at source and manage the hazardous waste store.","Select and audit permitted collectors and treaters and manage hazardous waste manifests.","Track the waste mass balance and recycling rate and file periodic reports.","Design reduction, packaging reuse, industrial symbiosis and material recovery programs.","Deliver extended producer responsibility (EPR) duties and train employees."]},competencies:[{name:{vi:"Phân định & phân loại chất thải",en:"Waste classification"},desc:{vi:"Xác định đúng chất thải nguy hại, công nghiệp thông thường và sinh hoạt theo nguồn và thành phần.",en:"Correctly identify hazardous, non-hazardous industrial and domestic waste by source and composition."}},{name:{vi:"Tuân thủ pháp luật môi trường",en:"Environmental compliance"},desc:{vi:"Bảo đảm lưu giữ, chuyển giao, chứng từ và báo cáo đúng quy định, lưu hồ sơ đầy đủ.",en:"Ensure lawful storage, handover, manifests and reporting with complete records."}},{name:{vi:"Phân tích dòng vật chất",en:"Material flow analysis"},desc:{vi:"Lập cân đối khối lượng, tìm điểm phát sinh lớn và cơ hội thu hồi giá trị.",en:"Build mass balances, find major waste sources and value recovery opportunities."}},{name:{vi:"Thiết kế giải pháp tuần hoàn",en:"Circular solution design"},desc:{vi:"Đề xuất tái sử dụng, thiết kế lại bao bì, cộng sinh công nghiệp và đo lường hiệu quả tuần hoàn.",en:"Propose reuse, packaging redesign and industrial symbiosis and measure circularity."}},{name:{vi:"Quản lý nhà thầu & chuỗi cung ứng",en:"Contractor & supply chain control"},desc:{vi:"Thẩm tra giấy phép, đánh giá định kỳ đơn vị xử lý và từ chối phương án giá rẻ trái luật.",en:"Verify permits, audit treaters regularly and reject cheap unlawful options."}}],knowledge:{vi:["Luật Bảo vệ môi trường số 72/2020/QH14: quản lý chất thải, kinh tế tuần hoàn và trách nhiệm mở rộng của nhà sản xuất.","Nghị định 08/2022/NĐ-CP và Thông tư 02/2022/TT-BTNMT: danh mục, mã chất thải, yêu cầu lưu giữ và chứng từ chất thải nguy hại.","Thứ bậc quản lý chất thải: phòng ngừa, giảm thiểu, tái sử dụng, tái chế, thu hồi năng lượng, xử lý và chôn lấp.","Công ước Basel về kiểm soát vận chuyển qua biên giới chất thải nguy hại.","ISO 14001:2015 và bộ tiêu chuẩn ISO 59000 về kinh tế tuần hoàn (ISO 59004, ISO 59020)."],en:["Law on Environmental Protection No. 72/2020/QH14: waste management, circular economy and extended producer responsibility.","Decree 08/2022/ND-CP and Circular 02/2022/TT-BTNMT: waste lists and codes, storage rules and hazardous waste manifests.","The waste hierarchy: prevention, reduction, reuse, recycling, energy recovery, treatment and landfill.","The Basel Convention on the control of transboundary movements of hazardous wastes.","ISO 14001:2015 and the ISO 59000 circular economy series (ISO 59004, ISO 59020)."]},tools:["Sổ phân định và nhật ký chất thải","Cân điện tử khu lưu giữ chất thải","Phần mềm quản lý dữ liệu môi trường","Hệ thống chứng từ chất thải nguy hại","Công cụ phân tích dòng vật chất (MFA)","Microsoft Excel và Power BI"],kpis:{vi:["Tỷ lệ tái chế và thu hồi vật liệu trên tổng chất thải phát sinh.","Khối lượng chất thải chôn lấp trên mỗi đơn vị sản phẩm.","Tỷ lệ chất thải nguy hại giao đúng đơn vị có giấy phép, đủ chứng từ (mục tiêu 100%).","Chi phí xử lý chất thải ròng sau khi trừ doanh thu phế liệu."],en:["Recycling and material recovery rate against total waste generated.","Landfilled waste per unit of output.","Share of hazardous waste handed to permitted operators with full manifests (target 100%).","Net waste cost after scrap revenue."]},day:[{time:"07:30",vi:"Kiểm tra khu lưu giữ: nhãn, biển cảnh báo, khay chống tràn và thời gian lưu giữ.",en:"Inspect the waste store: labels, warning signs, spill trays and storage time."},{time:"09:00",vi:"Cân, ghi sổ chất thải từ các xưởng và xử lý trường hợp phân loại sai tại nguồn.",en:"Weigh and log waste from each workshop and correct segregation errors at source."},{time:"11:00",vi:"Làm việc với đơn vị thu gom, kiểm tra giấy phép, phương tiện và ký chứng từ chuyển giao.",en:"Meet the collector, check permits and vehicles and sign the handover manifest."},{time:"14:00",vi:"Phân tích dòng vật chất, tìm cơ hội tái sử dụng bao bì và bán phế liệu sạch.",en:"Analyze material flows to find packaging reuse and clean scrap sales."},{time:"16:30",vi:"Cập nhật số liệu, báo cáo quản lý và kế hoạch đào tạo phân loại.",en:"Update data, report to management and plan segregation training."}],mistakes:{vi:["Xếp giẻ lau, vật liệu thấm hút dính dầu vào chất thải công nghiệp thông thường.","Tính đốt thu hồi năng lượng vào tỷ lệ tái chế, làm đẹp số liệu báo cáo.","Chọn đơn vị thu gom giá rẻ không có giấy phép, khiến chủ nguồn thải chịu trách nhiệm pháp lý."],en:["Classing oily rags and absorbents as ordinary industrial waste.","Counting energy recovery as recycling to flatter the report.","Choosing a cheap unpermitted collector, leaving the generator legally liable."]},career:[{vi:"Nhân viên môi trường nhà máy",en:"Plant environmental officer"},{vi:"Chuyên viên quản lý chất thải",en:"Waste management specialist"},{vi:"Trưởng nhóm kinh tế tuần hoàn",en:"Circular economy team lead"},{vi:"Trưởng phòng An toàn - Môi trường",en:"EHS Manager"}],glossary:[{term:"Hazardous waste",vi:"Chất thải nguy hại: chất thải chứa yếu tố độc, dễ cháy, ăn mòn, lây nhiễm hoặc đặc tính nguy hại khác.",en:"Waste with toxic, flammable, corrosive, infectious or other hazardous properties."},{term:"Waste manifest",vi:"Chứng từ chất thải nguy hại: tài liệu theo dõi chất thải từ chủ nguồn thải tới cơ sở xử lý.",en:"The document tracking hazardous waste from the generator to the treatment facility."},{term:"EPR",vi:"Trách nhiệm mở rộng của nhà sản xuất: nghĩa vụ tái chế hoặc đóng góp tài chính cho sản phẩm, bao bì đã bán ra.",en:"Extended producer responsibility: the duty to recycle, or fund recycling of, products and packaging sold."},{term:"Industrial symbiosis",vi:"Cộng sinh công nghiệp: chất thải, phụ phẩm của doanh nghiệp này làm nguyên liệu cho doanh nghiệp khác.",en:"One company's waste or by-products become another company's raw materials."},{term:"Recycling rate",vi:"Tỷ lệ tái chế: phần chất thải được tái chế hoặc ủ phân trên tổng lượng chất thải phát sinh.",en:"The share of generated waste that is recycled or composted."}],quiz:[{q:{vi:"Phát sinh 200 tấn: tái chế 70, ủ phân 20, đốt thu hồi năng lượng 40, chôn lấp 70. Tỷ lệ tái chế là bao nhiêu?",en:"200 t generated: 70 recycled, 20 composted, 40 energy recovery, 70 landfilled. What is the recycling rate?"},options:{vi:["65%","35%","55%","45%"],en:["65%","35%","55%","45%"]},answer:3,explain:{vi:"(70 + 20) / 200 = 45%; cộng cả đốt thu hồi năng lượng ra 65% là sai định nghĩa.",en:"(70 + 20) / 200 = 45%; adding energy recovery to get 65% misuses the definition."}},{q:{vi:"Theo thứ bậc quản lý chất thải, ưu tiên cao nhất là gì?",en:"What has the highest priority in the waste hierarchy?"},options:{vi:["Phòng ngừa và giảm thiểu phát sinh","Tái chế","Thu hồi năng lượng","Chôn lấp hợp vệ sinh"],en:["Prevention and reduction","Recycling","Energy recovery","Sanitary landfill"]},answer:0,explain:{vi:"Chất thải không phát sinh là chất thải tốt nhất; tái chế, thu hồi năng lượng và chôn lấp xếp sau.",en:"Waste never created is best; recycling, energy recovery and landfill come later."}},{q:{vi:"Đơn vị thu gom giá rẻ không có giấy phép đề nghị nhận chất thải nguy hại mà không cần chứng từ. Bạn làm gì?",en:"A cheap unpermitted collector offers to take hazardous waste without a manifest. What do you do?"},options:{vi:["Đồng ý vì tiết kiệm chi phí","Đồng ý nếu họ cam kết bằng miệng","Từ chối, chỉ giao cho đơn vị có giấy phép kèm chứng từ và báo cấp trên","Trộn vào chất thải thường"],en:["Agree to save money","Agree if they promise verbally","Refuse, use only permitted operators with manifests and escalate","Mix it into general waste"]},answer:2,explain:{vi:"Chủ nguồn thải chịu trách nhiệm khi chuyển giao sai; chỉ đơn vị có giấy phép và có chứng từ mới hợp pháp.",en:"The generator is liable for unlawful handover; only permitted operators with manifests are lawful."}},{q:{vi:"Văn bản nào hướng dẫn danh mục, mã chất thải và mẫu chứng từ chất thải nguy hại?",en:"Which instrument sets the waste list, waste codes and hazardous waste manifest form?"},options:{vi:["Luật Đầu tư","Thông tư 02/2022/TT-BTNMT","Luật Đất đai","ISO 9001"],en:["Investment Law","Circular 02/2022/TT-BTNMT","Land Law","ISO 9001"]},answer:1,explain:{vi:"Thông tư 02/2022/TT-BTNMT hướng dẫn Luật Bảo vệ môi trường, gồm danh mục chất thải và chứng từ chất thải nguy hại.",en:"Circular 02/2022/TT-BTNMT implements the Environmental Protection Law, including the waste list and manifests."}}],tools_en:["Waste classification register and logbook","Electronic scale at waste storage area","Environmental data management software","Hazardous waste manifest system","Material flow analysis (MFA) tools","Microsoft Excel and Power BI"]}}})})(window.KKR);
